// Chat.jsx
import React, { useEffect, useState, useRef } from "react";
import * as openpgp from "openpgp";
import { v4 as uuidv4 } from "uuid";
import {
  encryptPrivateKey,
  decryptPrivateKey,
  storePrivateKey,
  retrievePrivateKey,
  generateKeys,
  encryptMessage,
  decryptMessage,
} from "../utils/crypto";
import { sha256 } from "js-sha256";
import VideoChat from "./VideoChat";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./Chat.css"; // Стили для адаптивного дизайна и анимаций

// Основной компонент чата
const Chat = () => {
  // Состояния: история сообщений, ввод текста, выбранный файл (если отправляется файл)
  // Также режим чата: "group" или "private", ID получателя (для приватного чата)
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [file, setFile] = useState(null);
  const [chatType, setChatType] = useState("group");
  const [recipientId, setRecipientId] = useState("");
  // Ключи: собственный публичный ключ и публичный ключ собеседника
  const [keys, setKeys] = useState({
    publicKey: null,
    recipientPublicKey: null,
  });

  // useRef для хранения приватного ключа и WebSocket‑соединения (без перерендеров)
  const privateKeyRef = useRef(null);
  const wsRef = useRef(null);

  // Функция восстановления аккаунта – пользователь может повторно ввести секретную фразу,
  // чтобы расшифровать сохранённый зашифрованный ключ.
  const recoverAccount = async () => {
    try {
      const storedKey = await retrievePrivateKey();
      if (!storedKey) {
        toast.error("Приватный ключ не найден.");
        return;
      }
      const passphrase = prompt(
        "Введите секретную фразу для восстановления доступа:"
      );
      const decryptedKey = await decryptPrivateKey(storedKey, passphrase);
      privateKeyRef.current = decryptedKey;
      const extractedKey = await openpgp.readKey({ armoredKey: decryptedKey });
      const publicKey = extractedKey.toPublic().armor();
      setKeys((prev) => ({ ...prev, publicKey }));
      toast.success("Аккаунт успешно восстановлен.");
    } catch (err) {
      console.error("Ошибка восстановления аккаунта:", err);
      toast.error("Ошибка восстановления аккаунта");
    }
  };

  // Инициализация чата – генерируются или загружаются clientId и криптографические ключи,
  // устанавливается WebSocket‑соединение.
  useEffect(() => {
    const initChat = async () => {
      try {
        // 1. Генерация или получение уникального clientId (храним в localStorage)
        let clientId = localStorage.getItem("clientId");
        if (!clientId) {
          clientId = uuidv4();
          localStorage.setItem("clientId", clientId);
          toast.info(`Создан новый clientId: ${clientId}`);
        } else {
          toast.info(`Используется существующий clientId: ${clientId}`);
        }

        // 2. Загрузка приватного ключа из IndexedDB или генерация новых ключей
        let privateKey = await retrievePrivateKey();
        let publicKey;
        // Запрашиваем у пользователя секретную фразу для защиты ключей
        const passphrase = prompt(
          "Введите секретную фразу для защиты ваших ключей:"
        );
        if (!privateKey) {
          // Если ключ не найден – генерируем новые ключи
          const generatedKeys = await generateKeys();
          privateKey = generatedKeys.privateKey;
          publicKey = generatedKeys.publicKey;
          // Шифруем приватный ключ перед сохранением
          const protectedKey = await encryptPrivateKey(privateKey, passphrase);
          await storePrivateKey(protectedKey);
          toast.success("Ключи сгенерированы и сохранены");
        } else {
          // Если ключ найден – дешифруем его
          const protectedKey = privateKey;
          privateKey = await decryptPrivateKey(protectedKey, passphrase);
          const extractedKey = await openpgp.readKey({
            armoredKey: privateKey,
          });
          publicKey = extractedKey.toPublic().armor();
          toast.success("Приватный ключ загружен из хранилища");
        }
        privateKeyRef.current = privateKey;
        setKeys((prev) => ({ ...prev, publicKey }));

        // 3. Устанавливаем WebSocket‑соединение (с повторной инициализацией, если ещё нет)
        if (!wsRef.current) {
          toast.info("Инициализация WebSocket-соединения...");
          wsRef.current = new WebSocket("ws://localhost:8080");
        }
        // Обработка события открытия соединения
        wsRef.current.onopen = () => {
          toast.info("WebSocket подключен");
          // Отправляем сообщение типа "key_exchange" с нашим публичным ключом и clientId
          wsRef.current.send(
            JSON.stringify({
              type: "key_exchange",
              publicKey,
              clientId,
            })
          );
          console.log("Публичный ключ и clientId отправлены на сервер");
        };

        // Обработка входящих сообщений
        wsRef.current.onmessage = async (event) => {
          try {
            const data = JSON.parse(event.data);
            console.log("Получено сообщение от сервера:", data);

            // Если это обмен ключами – сохраняем публичный ключ собеседника
            if (data.type === "key_exchange" && data.publicKey) {
              setKeys((prev) => ({
                ...prev,
                recipientPublicKey: data.publicKey,
              }));
              toast.info("Получен публичный ключ другого клиента");
            }
            // Если это текстовое сообщение – расшифровываем его и добавляем в историю
            else if (data.type === "message") {
              try {
                const decryptedMessage = await decryptMessage(
                  data.encryptedMessage,
                  privateKeyRef.current
                );
                setMessages((prev) => [
                  ...prev,
                  { userId: data.clientId, text: decryptedMessage },
                ]);
              } catch (err) {
                console.error("Ошибка расшифровки сообщения:", err);
                toast.error("Ошибка расшифровки сообщения");
              }
            }
            // Дополнительно можно обработать другие типы (например, file, video_signal)
          } catch (err) {
            console.error("Ошибка обработки входящего сообщения:", err.message);
            toast.error("Ошибка обработки входящего сообщения");
          }
        };

        wsRef.current.onerror = (err) => {
          console.error("WebSocket error:", err);
          toast.error("Ошибка WebSocket-соединения");
        };

        wsRef.current.onclose = (event) => {
          console.log("WebSocket connection closed", event);
          wsRef.current = null;
          toast.info("Соединение с сервером закрыто");
        };
      } catch (err) {
        console.error("Ошибка инициализации чата:", err);
        toast.error("Ошибка инициализации чата");
      }
    };

    initChat();

    // Функция очистки (cleanup) при размонтировании компонента
    return () => {
      if (wsRef.current) {
        toast.info("Закрытие WebSocket-соединения при размонтировании.");
        wsRef.current.close();
      }
    };
  }, []);

  // Обработчик выбора файла для отправки (файловые вложения)
  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      // Берем первый выбранный файл
      setFile(e.target.files[0]);
    }
  };

  // Функция отправки сообщения (текстового или файлового)
  const sendMessage = async () => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      toast.error("WebSocket не подключен");
      return;
    }
    // Если чат приватный, проверяем наличие публичного ключа получателя
    if (chatType === "private" && !keys.recipientPublicKey) {
      toast.error("Публичный ключ получателя отсутствует");
      return;
    }
    try {
      const clientId = localStorage.getItem("clientId");
      let encryptedPayload;
      let messageType = "message";
      let additionalData = {};

      if (file) {
        // Если отправляется файл: читаем его как Base64
        const fileData = await new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = () => resolve(reader.result);
          reader.onerror = (error) => reject(error);
        });
        encryptedPayload = await encryptMessage(
          fileData,
          keys.recipientPublicKey
        );
        messageType = "file";
        additionalData = { fileName: file.name, fileType: file.type };
      } else {
        // Для текстового сообщения: шифруем введённый текст
        encryptedPayload = await encryptMessage(input, keys.recipientPublicKey);
      }

      // Формируем объект сообщения
      const messageObj = {
        type: messageType,
        encryptedMessage: encryptedPayload,
        clientId,
        chatType,
        ...additionalData,
      };

      // Если чат приватный – добавляем ID получателя
      if (chatType === "private") {
        messageObj.recipientId = recipientId;
      }

      // Отправляем сообщение через WebSocket
      wsRef.current.send(JSON.stringify(messageObj));
      toast.success("Сообщение отправлено");

      // Локально добавляем отправленное сообщение в историю
      setMessages((prev) => [
        ...prev,
        {
          userId: "Вы",
          text: messageType === "file" ? `[Файл: ${file.name}]` : input,
        },
      ]);

      // Очищаем поля ввода и выбранный файл
      setInput("");
      setFile(null);
    } catch (err) {
      console.error("Ошибка отправки сообщения:", err);
      toast.error("Ошибка отправки сообщения");
    }
  };

  return (
    <div className="chat-container">
      <h1>Anonymous Chat</h1>
      {/* Кнопка для восстановления доступа к аккаунту */}
      <button onClick={recoverAccount} className="recovery-btn">
        Восстановить аккаунт
      </button>
      {/* Переключатель типа чата */}
      <div className="chat-type">
        <label>
          <input
            type="radio"
            name="chatType"
            value="group"
            checked={chatType === "group"}
            onChange={() => setChatType("group")}
          />
          Групповой чат
        </label>
        <label>
          <input
            type="radio"
            name="chatType"
            value="private"
            checked={chatType === "private"}
            onChange={() => setChatType("private")}
          />
          Приватный чат
        </label>
      </div>
      {/* Если выбран приватный чат, запрашиваем ID собеседника */}
      {chatType === "private" && (
        <input
          type="text"
          value={recipientId}
          onChange={(e) => setRecipientId(e.target.value)}
          placeholder="Введите ID собеседника"
          className="recipient-input"
        />
      )}
      {/* Сообщения чата */}
      <div className="messages">
        {messages.map((msg, index) => (
          <p key={index} className="message">
            <strong>{msg.userId}:</strong> {msg.text}
          </p>
        ))}
      </div>
      {/* Область ввода сообщения и файлов */}
      <div className="input-area">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Введите сообщение..."
          className="text-input"
        />
        <input type="file" onChange={handleFileChange} className="file-input" />
        <button
          onClick={sendMessage}
          disabled={chatType === "private" && !keys.recipientPublicKey}
        >
          Отправить
        </button>
      </div>
      {/* Компонент видеозвонков */}
      <VideoChat
        ws={wsRef.current}
        clientId={localStorage.getItem("clientId")}
      />
      <ToastContainer position="bottom-right" autoClose={3000} />
    </div>
  );
};

export default Chat;
